from construire import Chapter,fig,box,qs,sub
from nouveaux_communs import diagnostic,exercices,bilan,DS5,DM6
from math import pi,sqrt,cos

def create():
 c=Chapter(9,'Superposition et interférences','1.6 / interférences','la somme de signaux de même fréquence, les interférences acoustiques et mécaniques, les chemins optiques et le dispositif des trous d’Young.')
 c.f('phasors',r'''\draw[axis](0,0)--(7,0)node[right]{Réel};\draw[axis](0,0)--(0,4.3)node[above]{Imaginaire};\draw[-{Stealth},very thick,otNavy](0,0)--(4,0)node[midway,below]{$A_1$};\draw[-{Stealth},very thick,otGreenDark](0,0)--(1.5,2.6)node[midway,left]{$A_2$};\draw[dashed,otMuted](4,0)--(5.5,2.6)--(1.5,2.6);\draw[-{Stealth},thick,otOrange](0,0)--(5.5,2.6)node[midway,above]{$\underline S$};\draw[otMuted](.9,0)arc(0:60:.9);\node[lab]at(1.3,.7){$\Delta\varphi$};\node[lab,text width=4cm,align=left]at(10,2){$|\underline S|^2=A_1^2+A_2^2$\\$\quad+2A_1A_2\cos\Delta\varphi$.};''')
 c.f('amplitude',r'''\begin{axis}[width=13.4cm,height=5.7cm,xmin=0,xmax=2,ymin=0,ymax=2.2,xlabel={$\Delta\varphi/\pi$},ylabel={$S_m/A$},axis lines=left,grid=major]\addplot[otNavy,thick,domain=0:2,samples=220]{2*abs(cos(deg(pi*x/2)))};\end{axis}''')
 c.f('young',r'''\draw[axis](-.5,0)--(12,0)node[right]{$z$};\draw[thick,otMuted](1,-2)--(1,-.9)(1,-.7)--(1,.7)(1,.9)--(1,2);\fill[otNavy](1,.8)circle(2pt)node[left=3mm]{$S_1$};\fill[otGreenDark](1,-.8)circle(2pt)node[left=3mm]{$S_2$};\draw[thick](10,-2)--(10,3.3)node[above]{Écran};\fill[otNavy](10,2.3)circle(2pt)node[right]{$M(x)$};\draw[ray](1,.8)--(10,2.3)node[midway,above]{$r_1$};\draw[raytwo](1,-.8)--(10,2.3)node[midway,below]{$r_2$};\draw[<->,otMuted](1,-2.4)--(10,-2.4)node[midway,below]{$D$};\draw[<->,otMuted](-.3,-.8)--(-.3,.8)node[midway,left]{$a$};\draw[-{Stealth},otMuted](10.8,0)--(10.8,2.3)node[midway,right]{$x$};\node[lab]at(5,-1.6){Schéma sans échelle ; $a,|x|\ll D$.};''')
 c.f('franges',r'''\begin{axis}[width=13.4cm,height=5.8cm,xmin=-2,xmax=2,ymin=0,ymax=4.4,xlabel={$x/i$},ylabel={$I/I_0$},axis lines=left,grid=major]\addplot[otNavy,thick,domain=-2:2,samples=300]{2*(1+cos(deg(2*pi*x)))};\end{axis}''')
 c.f('contraste',r'''\begin{axis}[width=13.4cm,height=5.8cm,xmin=0,xmax=2,ymin=0,ymax=4.4,xlabel={$\Delta\varphi/\pi$},ylabel={Intensité réduite},axis lines=left,grid=major,legend style={draw=none,font=\small,at={(.5,1.03)},anchor=south,legend columns=2}]\addplot[otNavy,thick,domain=0:2,samples=200]{2+2*cos(deg(pi*x))};\addlegendentry{$I_1=I_2=1$}\addplot[otGreenDark,thick,domain=0:2,samples=200]{1.25+cos(deg(pi*x))};\addlegendentry{$I_1=1$, $I_2=0,25$}\end{axis}''')
 c.intro='Deux perturbations peuvent se renforcer ou se compenser au même point. L’intensité observée dépend alors du déphasage accumulé le long des trajets, pas seulement de l’énergie de chaque onde prise séparément. Les interférences rendent ainsi mesurables de très petites différences de chemin.'
 c.mapping='Amplitude résultante de deux ondes de même fréquence ; conditions constructives et destructives ; déphasage et différence de chemin optique ; trous d’Young ; établissement de la différence de marche ; exploitation de la formule de Fresnel fournie ; caractérisation expérimentale.'
 c.prereq=r'Chapitre 8 : retard, phase et longueur d’onde. Chapitre 6 : addition complexe. Identités trigonométriques et approximation $\sqrt{1+u}\simeq1+u/2$ pour |u| très petit.'
 c.method='Fixer l’ordre des deux chemins et des phases ; calculer leur différence ; ajouter les phases initiales et éventuelles phases de réflexion ; utiliser la formule d’amplitude ou de Fresnel ; déterminer les maxima et minima ; vérifier les hypothèses de cohérence.'
 c.boundary='La formule de Fresnel lumineuse est fournie, conformément au programme. Le contraste et les lames minces sont des applications guidées ; la cohérence est expliquée au niveau nécessaire à l’expérience.'
 diagnostic(c,[(r'Additionner $A\cos\omega t$ à lui-même.',r'$2A\cos\omega t$ : l’amplitude double.'),(r'Additionner $A\cos\omega t$ et $A\cos(\omega t+\pi)$.',r'La somme est nulle à tout instant.'),(r'Un chemin supplémentaire λ donne quelle phase ?',r'Un retard de phase $-2\pi$, donc un retour en phase.'),(r'Un chemin supplémentaire λ/2 ?',r'Un déphasage de π modulo 2π : opposition.'),(r'Les intensités s’additionnent-elles toujours pour deux ondes cohérentes ?',r'Non, il existe un terme d’interférence ; additionner les champs avant d’obtenir l’intensité.'),(r'Un milieu d’indice n possède quelle célérité lumineuse ?',r'$c=c_0/n$ dans le modèle de la fréquence étudiée.'),(r'La fréquence lumineuse change-t-elle au passage d’un dioptre immobile ?',r'Non ; la longueur d’onde devient $\lambda_0/n$ dans le milieu.'),(r'Peut-on avoir une annulation totale si les deux amplitudes sont différentes ?',r'Non dans le modèle scalaire de deux sinus : le minimum d’amplitude est $|A_1-A_2|$.')])
 c.c('Additionner des signaux, pas des amplitudes',box('loi','Principe de superposition',r'Dans un milieu linéaire, la grandeur totale est $s=s_1+s_2$. Pour deux sinusoïdes de même pulsation :\[s=A_1\cos(\omega t+\varphi_1)+A_2\cos(\omega t+\varphi_2).\]La somme est une sinusoïde de même pulsation ; son amplitude dépend de $\Delta\varphi=\varphi_2-\varphi_1$.')+sub('Trois cas immédiats',r'En phase, la somme a l’amplitude $A_1+A_2$. En opposition, elle a l’amplitude $|A_1-A_2|$. En quadrature, le carré de l’amplitude vaut $A_1^2+A_2^2$. On ne peut donc additionner les amplitudes positives que dans le premier cas.')+sub('Le rôle du lieu d’observation',r'Les phases reçues en un point dépendent des phases d’émission et des distances parcourues. Déplacer le récepteur change la différence de chemin et peut transformer un maximum en minimum. La fréquence reste celle des sources dans le cas étudié.')+box('methode','Fixer une convention',r'Dans ce chapitre, $\Delta\varphi=\varphi_2-\varphi_1$ et $\delta=L_2-L_1$. Avec la convention temporelle $e^{j\omega t}$, la propagation donne $\Delta\varphi=\Delta\varphi_{\rm source}-2\pi\delta/\lambda$. Le cosinus de cette phase est insensible au signe global, mais les déplacements de franges ne le sont pas.'))
 c.c('Construire l’amplitude résultante',fig('phasors','La somme vectorielle des amplitudes complexes permet de traiter des amplitudes différentes.')+box('loi','Somme de deux sinus de même fréquence',r'\[S_m^2=A_1^2+A_2^2+2A_1A_2\cos\Delta\varphi.\]Cette identité se déduit du module au carré de $A_1e^{j\varphi_1}+A_2e^{j\varphi_2}$. Elle implique $|A_1-A_2|\leq S_m\leq A_1+A_2$.')+sub('Exemple',r'A1 = 3 mm, A2 = 4 mm et Δφ = π/2 donnent Sm = 5 mm. Pour Δφ = π, le minimum vaut 1 mm : il reste une vibration. La phase de la somme peut être calculée avec l’argument du complexe total ; elle est indéfinie quand l’amplitude totale est nulle.'))
 c.c('Le cas d’amplitudes égales',box('loi','Identité trigonométrique',r'\[s=2A\cos\left(\frac{\Delta\varphi}{2}\right)\cos\left(\omega t+\frac{\varphi_1+\varphi_2}{2}\right).\]\[S_m=2A\left|\cos\left(\frac{\Delta\varphi}{2}\right)\right|.\]Le coefficient devant le second cosinus peut être négatif ; l’amplitude physique est positive. Un changement de signe est absorbé dans une phase de π.')+fig('amplitude','L’amplitude est maximale en phase, nulle en opposition et périodique en déphasage.')+sub('Conditions',r'Constructif : $\Delta\varphi=2m\pi$. Destructif : $\Delta\varphi=(2m+1)\pi$. Une annulation complète exige en plus des amplitudes égales. « Destructif » peut donc désigner un minimum non nul si les amplitudes sont inégales.'))
 c.c('Interférences acoustiques et mécaniques',sub('Deux sources synchronisées',r'Pour des chemins géométriques d1 et d2 dans le même milieu de longueur d’onde λ :\[\Delta\varphi=\Delta\varphi_0-\frac{2\pi}{\lambda}(d_2-d_1).\]Avec des sources en phase et sans déphasage de réflexion, les maxima vérifient $d_2-d_1=m\lambda$ et les minima $d_2-d_1=(m+1/2)\lambda$.')+box('methode','Un exemple sonore',r'À 1 kHz et c = 340 m/s, λ = 0,340 m. Une différence de trajet de 0,170 m produit une opposition pour des émissions en phase. Si l’on inverse électriquement un haut-parleur, on ajoute π : le même lieu devient constructif.')+sub('La géométrie des lieux',r'Dans un plan, les lieux de différence constante de distance à deux points sont des hyperboles, sauf cas dégénérés. Sur la médiatrice des sources, les distances sont égales. Le son ne disparaît pas partout lorsqu’un minimum apparaît : l’interférence redistribue les amplitudes selon le lieu.')+box('piege','Réflexion et phase initiale',r'Une différence de trajet seule ne suffit pas si une réflexion ajoute une phase ou si les sources ne sont pas en phase. Ajouter toutes les contributions avant d’appliquer la condition de maximum.'))
 c.c('De l’onde lumineuse à l’intensité',box('loi','Formule de Fresnel fournie',r'Pour deux ondes lumineuses cohérentes dans le modèle scalaire :\[I=I_1+I_2+2\sqrt{I_1I_2}\cos\Delta\varphi.\]L’intensité est liée à une moyenne temporelle du carré du champ ; elle n’est pas le champ lui-même. Pour $I_1=I_2=I_0$, $I=2I_0(1+\cos\Delta\varphi)$.')+sub('Pourquoi une cohérence est nécessaire',r'Si la phase relative varie très rapidement de façon désordonnée pendant la mesure, la moyenne du terme cosinus s’annule. On observe alors $I_1+I_2$. Deux lampes indépendantes ne produisent donc pas en général une figure d’interférences stable. Les deux trous d’Young sont éclairés par une même source afin de produire deux ondes reliées en phase.')+sub('Conditions du modèle',r'On suppose une même fréquence, une relation de phase stable sur la durée et les chemins étudiés, et des états de polarisation compatibles. La théorie complète de cohérence n’est pas requise ici. Dans un montage réel, l’étendue de source et la largeur spectrale limitent la visibilité.')+box('piege','Une lumière monochromatique idéale',r'Une source réelle a une largeur spectrale finie. « Monochromatique » est une approximation adaptée aux distances de l’expérience, pas une preuve de cohérence à toute différence de chemin.'))
 c.c('Le chemin optique',box('loi','De la distance au déphasage',r'Dans un milieu homogène d’indice n, le chemin optique est $\mathcal L=n\ell$. Pour plusieurs portions, $\mathcal L=\sum n_i\ell_i$. En prenant $\lambda_0$ dans le vide :\[\Delta\varphi=\Delta\varphi_0-\frac{2\pi}{\lambda_0}(\mathcal L_2-\mathcal L_1).\]La différence de chemin optique est une longueur, pas une phase.')+sub('La fréquence est conservée',r'La longueur d’onde dans un milieu vaut $\lambda=\lambda_0/n$. Écrire la phase comme $2\pi n\ell/\lambda_0$ ou $2\pi\ell/\lambda$ est équivalent pour une portion homogène. Ne pas employer à la fois n et la longueur d’onde déjà divisée par n : ce serait compter deux fois l’indice.')+sub('Insérer une lame',r'Une lame d’épaisseur e et d’indice n, placée normalement sur un trajet initialement dans l’air assimilé au vide, remplace e de chemin optique par ne. Elle ajoute donc $(n-1)e$ à ce trajet. Dans un bras seulement, elle déplace la figure sans changer l’interfrange si les autres paramètres restent fixes.')+box('methode','Réflexions',r'Une phase de réflexion éventuellement fournie doit être ajoutée séparément au déphasage de propagation. La différence géométrique ne la contient pas.'))
 c.c('La géométrie des trous d’Young',fig('young','Les trous sont en x = +a/2 pour S1 et -a/2 pour S2. Dans cette convention, r2 est plus long que r1 pour x positif.')+sub('Établir la différence de marche',r'En air assimilé au vide : $r_1=\sqrt{D^2+(x-a/2)^2}$ et $r_2=\sqrt{D^2+(x+a/2)^2}$. Pour $a,|x|\ll D$ :\[r_1\simeq D+\frac{(x-a/2)^2}{2D},\quad r_2\simeq D+\frac{(x+a/2)^2}{2D}.\]\[\delta=r_2-r_1\simeq\frac{ax}{D}.\]')+box('piege','Un signe qui suit les noms',r'Inverser S1 et S2 inverse δ. La figure symétrique d’intensité ne change pas, mais une lame ou une phase initiale impose de garder la convention jusqu’au déplacement des franges.'))
 c.c('Interfrange et positions des franges',box('loi','Sources en phase et intensités égales',r'\[I(x)=2I_0\left[1+\cos\left(\frac{2\pi ax}{\lambda_0D}\right)\right].\]Franges brillantes : $x_m=m\lambda_0D/a$. Franges sombres : $x=(m+1/2)\lambda_0D/a$.\[i=\frac{\lambda_0D}{a}.\]L’interfrange sépare deux maxima voisins ou deux minima voisins, pas un maximum du minimum adjacent.')+fig('franges','Figure idéale sans enveloppe de diffraction, intensités égales et source axiale.')+sub('Un exemple',r'λ0 = 600 nm, D = 2,00 m et a = 0,50 mm donnent i = 2,40 mm. Les premières franges sombres sont à ±1,20 mm. L’intensité maximale vaut 4I0, alors que chaque trou seul donne I0.'))
 c.c('Contraste et amplitudes différentes',fig('contraste','Avec des intensités inégales, les minima restent non nuls et la modulation est moins contrastée.')+box('loi','Application guidée de Fresnel',r'\[I_{\max}=(\sqrt{I_1}+\sqrt{I_2})^2,\quad I_{\min}=(\sqrt{I_1}-\sqrt{I_2})^2.\]\[\mathcal C=\frac{I_{\max}-I_{\min}}{I_{\max}+I_{\min}}=\frac{2\sqrt{I_1I_2}}{I_1+I_2}.\]Ce contraste idéal vaut 1 si les intensités sont égales et décroît en cas de déséquilibre.')+sub('Diagnostic expérimental',r'Une baisse de contraste peut venir d’un déséquilibre d’intensité, d’une cohérence insuffisante, d’un fond lumineux ou d’un capteur saturé. Mesurer chaque trou séparément et soustraire un fond mesuré permet de tester ces causes. Un minimum non nul ne prouve donc pas à lui seul un défaut de cohérence.'))
 c.c('Déplacer et mesurer les franges',sub('Une phase initiale imposée',r'Avec $\Delta\varphi=\Delta\varphi_0-2\pi ax/(\lambda_0D)$, les maxima satisfont cette phase égale à 2mπ. Une variation de phase déplace toute la figure d’une quantité $\Delta x=\lambda_0D\,\Delta\varphi_0/(2\pi a)$, avec le signe donné par la convention choisie.')+box('methode','Lame sur le trajet 2',r'Si la lame ajoute $(n-1)e$ à $\mathcal L_2$, alors $\delta=ax/D+(n-1)e$. La frange d’ordre zéro vérifie δ = 0 et se déplace de $x_0=-D(n-1)e/a$. L’interfrange est conservé dans cette approximation. Une seule position finale ne donne que l’ordre modulo i si l’on n’a pas suivi le déplacement.')+sub('Mesurer une longueur d’onde',r'Mesurer N interfranges sur une distance L ; utiliser i = L/N puis $\lambda_0=ia/D$. Les incertitudes de i, a et D doivent être discutées. Augmenter D élargit les franges mais réduit souvent l’éclairement ; réduire a élargit aussi les franges, avec des contraintes pratiques sur les ouvertures.')+box('docu','Une représentation schématique',r'L’enveloppe de diffraction des trous réels n’est pas incluse dans la formule idéale précédente. Travailler dans la région où les deux intensités sont suffisamment proches et lentement variables.'))
 c.c('Interpréter les limites du modèle',sub('Conservation et redistribution',r'Un maximum peut recevoir quatre fois l’intensité d’un trou seul, tandis qu’un minimum en reçoit zéro. Il n’y a pas création d’énergie locale par la formule : l’ensemble du champ distribue différemment le flux dans l’espace. Une annulation à un point ne signifie pas que chaque onde y cesse d’exister séparément.')+sub('Même fréquence, phases stables',r'Les interférences stationnaires étudiées supposent des fréquences égales. Deux fréquences proches donnent une amplitude modulée dans le temps, appelée battement ; c’est un prolongement guidé, pas une figure fixe décrite par une phase relative constante. Un détecteur lent peut moyenner cette modulation.')+box('methode','Une rédaction complète',r'Préciser les sources, la cohérence supposée, les amplitudes reçues, la convention de δ et les éventuelles phases de réflexion. Établir δ avant d’écrire les conditions de maximum et minimum. Pour Young, annoncer l’approximation paraxiale et les limites de l’enveloppe.')+box('piege','Trois grandeurs',r'Distinguer l’amplitude de champ A, l’intensité I proportionnelle à $A^2$ et l’amplitude de modulation du profil d’intensité. Un rapport d’intensités 4 correspond à un rapport d’amplitudes 2.'))
 c.tp_title='Mesurer un interfrange'
 c.tp=fig('young','Travailler avec un dispositif optique prévu pour la classe et conserver le faisceau sous le niveau des yeux.')+sub('Protocole',r'Éclairer deux trous ou deux fentes étroites par une même source monochromatique. Mesurer D et l’écartement a. Relever une distance couvrant dix interfranges, puis répéter la lecture. Masquer chaque ouverture séparément pour comparer les intensités et observer l’enveloppe.')+sub('Données simulées',r'a = 0,500 mm, D = 2,000 m et L = 24,0 mm pour N = 10. Avec u(a) = 0,005 mm, u(D) = 0,005 m et u(L) = 0,2 mm indépendantes, déterminer λ0 et son incertitude-type.')+box('methode','Exploitation corrigée',r'i = 2,40 mm et λ0 = ia/D = 600 nm. L’incertitude relative est $\sqrt{(0{,}2/24)^2+(0{,}005/0{,}500)^2+(0{,}005/2{,}000)^2}=0{,}01326$, donc u(λ0) ≈ 8 nm. Compter dix intervalles exige de repérer onze maxima. Le jeu fourni est simulé.')
 c.num_title='Faire varier une différence de phase'
 c.num=r'''Le code calcule la formule de Fresnel et compare une figure équilibrée à une figure déséquilibrée. Les unités de x sont les mètres.
\begin{verbatim}
import numpy as np
import matplotlib.pyplot as plt
lam, D, a = 600e-9, 2., 0.5e-3
i = lam*D/a
x = np.linspace(-3*i, 3*i, 6001)
delta = a*x/D
profiles = {}
for I2 in (1., 0.25):
    I1 = 1.
    phase = -2*np.pi*delta/lam
    I = I1 + I2 + 2*np.sqrt(I1*I2)*np.cos(phase)
    profiles[I2] = I
    plt.plot(x*1e3, I, label=f"I2={I2}")
plt.xlabel("x (mm)"); plt.ylabel("I / Iref")
plt.grid(); plt.legend(); plt.tight_layout()
\end{verbatim}
Les extrema sont 0 et 4 pour les intensités égales ; 0,25 et 2,25 pour I2 = 0,25. Les contrastes valent 1 et 0,8. Ajouter une phase initiale dans le code translate les franges ; doubler a divise i par deux. Contrôler le sens du déplacement avec la convention explicite de δ avant de lire le tracé.
'''
 bilan(c,r'$S_m^2=A_1^2+A_2^2+2A_1A_2\cos\Delta\varphi$. Fresnel : $I=I_1+I_2+2\sqrt{I_1I_2}\cos\Delta\varphi$. $\Delta\varphi=\Delta\varphi_0-2\pi\delta/\lambda_0$. Pour Young en air : δ ≈ ax/D et i = λ0D/a.',r'Faire l’inventaire des phases, choisir δ, établir la géométrie, appliquer la formule fournie puis interpréter le contraste et les limites. Indiquer les hypothèses de cohérence et les approximations de distance.',r'Additionner les intensités de deux ondes cohérentes sans terme croisé ; confondre chemin optique et géométrique ; oublier une phase de réflexion ; annoncer une annulation avec amplitudes inégales ; compter un demi-interfrange comme i.')
 c.td_titles=['Additionner deux sinus','Conditions d’interférence','Trajets acoustiques','Chemins optiques','Trous d’Young','Mesures et contraste','Déplacer une figure','Interpréter un résultat']
 exercices(c,[
 ('Deux signaux en phase',r'A1 = 2 mm et A2 = 3 mm, même fréquence et même phase. Donner l’amplitude totale.',r'Sm = A1 + A2 = 5 mm. La phase est la phase commune ; ce cas particulier permet l’addition des amplitudes positives.'),
 ('Une opposition incomplète',r'Mêmes amplitudes que E01 mais opposition de phase. Donner le minimum.',r'Sm = |3 - 2| = 1 mm. La somme garde la phase du signal d’amplitude 3 mm. L’interférence est destructive sans être une annulation totale.'),
 ('En quadrature',r'A1 = 3 mm, A2 = 4 mm et Δφ = π/2. Donner Sm.',r'$S_m=\sqrt{3^2+4^2}=5$ mm. Le terme croisé est nul ; les amplitudes ne s’additionnent pas.'),
 ('Une phase intermédiaire',r'Deux ondes d’amplitude A = 2 mm ont un déphasage 2π/3. Donner Sm.',r'$S_m=2A|\cos(\pi/3)|=A=2$ mm. Le coefficient trigonométrique et l’amplitude sont ici positifs.'),
 ('Un rapport d’intensités',r'Une onde a une amplitude double d’une autre. Quel est le rapport des intensités dans le même modèle ?',r'L’intensité étant proportionnelle au carré de l’amplitude, le rapport vaut 4. Les coefficients de proportionnalité doivent être les mêmes pour cette comparaison.'),
 ('Des extrema',r'I1 = 9 et I2 = 4 en unités communes. Calculer Imax et Imin.',r'$I_{\max}=(3+2)^2=25$ ; $I_{\min}=(3-2)^2=1$. Le contraste idéal est (25 - 1)/(25 + 1) = 12/13.'),
 ('Un son destructif',r'f = 1 kHz, c = 340 m/s, sources en phase. Donner la plus petite différence positive de trajet produisant un minimum.',r'λ = 0,340 m. Le premier minimum est à δ = λ/2 = 0,170 m, en l’absence de phase supplémentaire.'),
 ('Une inversion de source',r'Pour E07, une source reçoit une inversion de phase π. Que se passe-t-il au même point ?',r'La phase totale devient π - 2π(1/2) = 0 modulo 2π. Le lieu devient constructif. La différence géométrique seule ne détermine pas le résultat.'),
 ('Une réflexion déphasante',r'Deux trajets sonores diffèrent de δ. Le second ajoute une phase π à la réflexion. Écrire la condition constructive.',r'$\Delta\varphi=\pi-2\pi\delta/\lambda=2m\pi$ impose $\delta=(m^{\prime}+1/2)\lambda$ avec un entier $m^{\prime}$. Les conditions habituelles sont échangées.'),
 ('Une lame transparente',r'n = 1,50 et e = 12 μm remplacent la même épaisseur d’air sur le trajet 2. Donner le chemin optique ajouté.',r'$(n-1)e=6\ \mu$m. À λ0 = 600 nm, cela vaut dix longueurs d’onde : déphasage supplémentaire -20π, équivalent à zéro à cette seule fréquence.'),
 ('Longueur d’onde dans le verre',r'λ0 = 600 nm et n = 1,50. Donner λ et comparer les phases sur une épaisseur e.',r'λ = λ0/n = 400 nm. La phase accumulée est $-2\pi ne/\lambda_0=-2\pi e/\lambda$. Employer ne et λ simultanément compterait l’indice deux fois.'),
 ('Une différence optique',r'Les chemins géométriques sont égaux ; l’un contient 2 mm d’air, l’autre 2 mm d’un milieu d’indice 1,25. Calculer δ.',r'La différence de chemin optique est (1,25 - 1) × 2 mm = 0,50 mm. Les chemins géométriques égaux ne garantissent pas des phases égales si les indices diffèrent.'),
 ('Calculer l’interfrange',r'λ0 = 500 nm, D = 1,50 m et a = 0,30 mm. Calculer i.',r'$i=\lambda_0D/a=2{,}50$ mm. Le quotient doit être effectué en unités cohérentes.'),
 ('Une frange sombre',r'Pour E13, donner les deux premières positions sombres de part et d’autre du centre.',r'Les plus proches sont x = ±i/2 = ±1,25 mm ; les suivantes x = ±3i/2 = ±3,75 mm. La frange centrale est brillante pour les sources en phase.'),
 ('Changer la géométrie',r'Que devient i si D double et a triple ?',r'$i^{\prime}/i=(2D/D)/(3a/a)=2/3$. La longueur d’onde est supposée inchangée ; l’approximation paraxiale doit rester valable.'),
 ('Mesurer λ0',r'12 interfranges occupent 30,0 mm ; a = 0,40 mm et D = 2,00 m. Déterminer λ0.',r'i = 30/12 = 2,50 mm, puis λ0 = ia/D = 500 nm. Il faut distinguer le nombre de maxima du nombre d’intervalles.'),
 ('Le contraste d’un déséquilibre',r'I2 = I1/4. Calculer le contraste idéal.',r'$\mathcal C=2\sqrt{1/4}/(1+1/4)=1/1{,}25=0{,}80$. Le minimum est I1/4 et le maximum 9I1/4.'),
 ('Un fond lumineux',r'Une figure idéale varie entre 0 et 4 unités ; un fond uniforme de 1 unité est ajouté. Quel contraste est mesuré ?',r'Les extrema deviennent 1 et 5 ; $\mathcal C=(5-1)/(5+1)=2/3$. Une perte de contraste peut donc provenir du fond sans changement de cohérence.'),
 ('Une lame déplace le centre',r'Young : D = 2 m, a = 0,50 mm, λ0 = 600 nm. Une lame n = 1,50, e = 1,20 μm est placée sur le trajet 2. Donner x0 avec δ = ax/D + (n-1)e.',r'$x_0=-D(n-1)e/a=-2{,}40$ mm = -i. La figure finale coïncide avec la figure initiale par périodicité, même si la frange d’ordre zéro s’est déplacée d’un interfrange.'),
 ('Une phase imposée',r'$\Delta\varphi_0=\pi/2$ dans $\Delta\varphi=\Delta\varphi_0-2\pi x/i$. Où est le maximum de phase nulle ?',r'$x_0=i\Delta\varphi_0/(2\pi)=i/4$. Le signe vient de la convention affichée ; inverser l’ordre de δ sans changer la phase source donnerait une incohérence.'),
 ('Des sources indépendantes',r'Deux sources lumineuses de même fréquence moyenne sont indépendantes. Pourquoi n’observe-t-on pas nécessairement de franges stables ?',r'La phase relative peut fluctuer pendant l’intégration du détecteur. La moyenne du terme croisé devient nulle ; les intensités s’additionnent. Une fréquence moyenne égale n’assure pas une relation de phase stable.'),
 ('Une formule exacte',r'Pour les trous en ±a/2, montrer que $r_2-r_1=2ax/(r_1+r_2)$ puis retrouver δ ≈ ax/D.',r'Rationaliser : $(r_2-r_1)(r_2+r_1)=r_2^2-r_1^2=(x+a/2)^2-(x-a/2)^2=2ax$. Si r1 + r2 ≈ 2D, alors δ ≈ ax/D.'),
 ('L’intensité centrale',r'Sources de même intensité I0 avec phase initiale π. Donner I(0) et les premiers maxima en Young.',r'Au centre, les chemins sont égaux et la phase totale vaut π : I(0) = 0. Les premiers maxima sont x = ±i/2. L’interfrange reste i.'),
 ('Une énergie mystérieuse ?',r'Un maximum donne 4I0 alors que chaque onde seule donne I0. Cela viole-t-il la conservation de l’énergie ?',r'Non. L’interférence redistribue l’intensité : d’autres régions deviennent moins éclairées. La conservation s’évalue sur l’ensemble du flux et du dispositif, pas en additionnant les intensités isolées en un point cohérent.')])
 c.d('Mesurer l’indice d’une lame par déplacement',r'Deux trous d’Young ont a = 0,500 mm, D = 2,00 m et λ0 = 600 nm. Une lame d’épaisseur e = 10,0 μm, d’indice inconnu n, est introduite progressivement sur le trajet 2. On suit un déplacement de la frange d’ordre zéro de -20,0 mm.'+qs(r'Établir l’expression de δ et relier x0 à n.',r'Déterminer n et le nombre de franges ayant défilé.',r'Expliquer pourquoi une simple photographie finale ne suffit pas à lever le nombre de franges.',r'Avec u(x0) = 0,2 mm et u(e) = 0,2 μm, les autres grandeurs étant exactes et les incertitudes indépendantes, estimer u(n).'),'1. Lame : supplément (n-1)e. 2. Le centre suivi satisfait δ = 0. 3. Propager l’incertitude sur n-1.',r'$\delta=ax/D+(n-1)e$ et $x_0=-D(n-1)e/a$. Donc $n-1=-ax_0/(De)=0{,}500$ et n = 1,500. L’interfrange vaut 2,40 mm ; le défilement est 20/2,4 = 8,333 franges. La figure est périodique : une photographie finale donne le décalage modulo i, sans le nombre entier de franges passées. Le suivi continu ou une autre mesure est nécessaire. $u(n)=|n-1|\sqrt{[u(x_0)/|x_0|]^2+[u(e)/e]^2}=0{,}5\sqrt{0{,}01^2+0{,}02^2}=0{,}0112$. La mesure est compatible avec n = 1,50 à cette précision ; il faudrait inclure a et D si leurs incertitudes n’étaient pas négligeables.')
 c.d('Retrouver un déséquilibre d’intensité',r'Une figure d’interférences cohérentes présente un contraste 0,60 après soustraction du fond. On suppose des phases stables et on note r = I2/I1 ≤ 1.'+qs(r'Établir $\mathcal C=2\sqrt r/(1+r)$.',r'Résoudre pour r en posant u = √r.',r'Prédire les extrema en unités de I1.',r'Un fond de 0,50I1 est maintenant ajouté. Calculer le nouveau contraste.',r'Pourquoi faut-il justifier le modèle avant de déduire un rapport d’intensités d’un contraste ?'),'1. Utiliser les extrema de Fresnel. 2. La racine u doit être au plus 1. 3. Le fond augmente les deux extrema du même montant.',r'$\mathcal C=2\sqrt r/(1+r)$. Avec u = √r : $0{,}60u^2-2u+0{,}60=0$, soit u = 1/3 ou 3. La condition r ≤ 1 impose u = 1/3, donc r = 1/9. Les extrema valent $(1+1/3)^2I_1=16I_1/9$ et $(1-1/3)^2I_1=4I_1/9$. Après ajout de 0,50I1, le contraste est $(16/9-4/9)/(16/9+4/9+1)=12/29=0{,}4138$. Si les sources étaient partiellement incohérentes, si le fond n’était pas retiré ou si le détecteur saturait, la même visibilité ne conduirait pas nécessairement à r = 1/9. Mesurer chaque voie séparément permet de contrôler cette interprétation.')
 c.d('Deux étoiles : additionner deux figures',r'Un modèle fourni donne les figures produites séparément par deux étoiles incohérentes : $I_\pm=2I_0\{1+\cos[2\pi a(x/D\mp\varepsilon)/\lambda_0]\}$. Les intensités des étoiles s’additionnent. On suppose ε très petit.'+qs(r'Exprimer l’intensité totale comme constante plus produit de cosinus.',r'Donner le contraste en fonction de a.',r'Déterminer la plus petite séparation a donnant un contraste nul.',r'Pour λ0 = 600 nm et cette séparation a = 75,0 mm, calculer la séparation angulaire 2ε.',r'Pourquoi additionne-t-on ici des intensités alors qu’on additionnait des amplitudes entre les trous ?'),'1. Utiliser cos(u-v)+cos(u+v). 2. Le contraste est une valeur positive. 3. Les deux étoiles n’ont pas de phase relative stable.',r'$I=4I_0[1+\cos(2\pi ax/(\lambda_0D))\cos(2\pi a\varepsilon/\lambda_0)]$. Les extrema donnent $\mathcal C=|\cos(2\pi a\varepsilon/\lambda_0)|$. La première annulation est à $a\varepsilon=\lambda_0/4$. Donc $2\varepsilon=\lambda_0/(2a)=4{,}00\times10^{-6}$ rad, environ 0,825 seconde d’arc. Chaque étoile éclaire les deux trous de façon cohérente et produit sa propre figure ; les deux étoiles sont incohérentes entre elles et leurs figures s’additionnent en intensité. La visibilité disparaît lorsque les maxima de l’une comblent les minima de l’autre. Ce problème est un approfondissement guidé : la loi fournie contient la géométrie de l’éclairage incliné.')
 c.dm_title='DM — Un montage de Young déséquilibré'
 c.dm=r'On donne λ0 = 600 nm, D = 1,80 m, a = 0,450 mm, I1 = 4 unités et I2 = 1 unité. Les sources sont cohérentes et en phase. On adopte δ = r2 - r1 ≈ ax/D.'+sub('A. Figure initiale — 10 points',qs(r'Établir δ à partir des distances exactes. (3)',r'Écrire I(x) avec Fresnel et calculer i. (3)',r'Donner Imax, Imin et le contraste. (4)'))+sub('B. Une lame — 6 points',qs(r'Une lame d’indice 1,50 et d’épaisseur 0,60 μm est placée sur le trajet 2. Donner δ nouveau et x0. (4)',r'Que vaut alors I au centre géométrique x = 0 ? (2)'))+sub('C. Mesure — 4 points',qs(r'Proposer une mesure de λ0 sur plusieurs franges et expliquer comment distinguer déséquilibre et fond lumineux. (4)'))
 c.dm_sol=sub('A — 10 points',r'$r_{1,2}=\sqrt{D^2+(x\mp a/2)^2}$ ; la rationalisation donne δ = 2ax/(r1 + r2) ≈ ax/D (3). $I=5+4\cos(2\pi x/i)$, i = 2,40 mm (3). Imax = 9, Imin = 1, contraste 8/10 = 0,80 (4).')+sub('B — 6 points',r'Le trajet 2 gagne (n - 1)e = 0,30 μm = λ0/2. $\delta=ax/D+0{,}30\ \mu$m et $x_0=-D(0{,}30\ \mu\mathrm m)/a=-1{,}20$ mm (4). Au centre géométrique, la phase vaut π modulo 2π ; I(0) = 1 unité, minimum non nul à cause du déséquilibre (2).')+sub('C — 4 points',r'Mesurer une longueur couvrant N interfranges, puis λ0 = (L/N)a/D (2). Masquer chaque ouverture pour mesurer I1 et I2 ; mesurer le fond avec les deux voies masquées, puis le soustraire avant d’interpréter le contraste (2).')
 c.ds_title='DS — Du son à la lumière'
 c.ds=[sub('A. Deux ondes acoustiques — 7 points',r'Deux sources en phase émettent à 850 Hz dans l’air à 340 m/s. Au point M, les amplitudes reçues sont 0,30 Pa et 0,20 Pa ; le trajet 2 dépasse le trajet 1 de 0,20 m.'+qs(r'Calculer λ et le déphasage reçu. (2)',r'Déterminer l’amplitude totale. (2)',r'Que devient-elle si l’on inverse la phase de la source 2 ? (2)',r'Pourquoi le premier minimum n’est-il pas nul ? (1)'))+sub('B. Young — 9 points',r'λ0 = 500 nm, a = 0,250 mm, D = 1,50 m, intensités égales I0.'+qs(r'Établir δ puis I(x). (4)',r'Calculer i et les deux positions sombres les plus proches du centre. (3)',r'Que devient i si l’expérience entière est placée dans un milieu transparent d’indice 1,25 ? (2)')),
 sub('C. Interprétation expérimentale — 4 points',qs(r'Une figure possède Imax = 10 et Imin = 2 unités. Calculer son contraste. (1)',r'On mesure un fond uniforme de 1 unité. Donner le contraste après soustraction. (1)',r'Ce résultat permet-il à lui seul de déterminer si la source est partiellement incohérente ? Justifier et proposer un contrôle. (2)'))]
 c.ds_sol=[sub('A — 7 points',r'λ = 340/850 = 0,400 m ; Δφ = -2π(0,20/0,40) = -π (2). Sm = |0,30 - 0,20| = 0,10 Pa (2). L’inversion ajoute π, donc les ondes deviennent en phase et Sm = 0,50 Pa (2). L’annulation totale exige des amplitudes égales (1).')+sub('B — 9 points',r'Les distances donnent $\delta\simeq ax/D$ ; la phase reçue est $-2\pi\delta/\lambda_0$. Fresnel donne $I=2I_0[1+\cos(2\pi ax/(\lambda_0D))]$ (4). i = 3,00 mm ; minima proches à ±1,50 mm (3). En milieu uniforme, λ = λ0/n ; i devient i/n = 2,40 mm si a et D géométriques sont inchangés (2).'),sub('C — 4 points',r'Contraste brut : (10 - 2)/(10 + 2) = 2/3 (1). Après soustraction, extrema 9 et 1 : contraste 8/10 = 0,80 (1). Ce contraste peut provenir d’un déséquilibre avec cohérence parfaite, ou d’autres limitations. Mesurer chaque voie séparément et vérifier sa stabilité ; comparer au contraste idéal prédit par les deux intensités avant d’invoquer un défaut de cohérence (2).')]
 c.hints='E06 : prendre les racines des intensités. E09 : ajouter la phase de réflexion. E19 : le centre satisfait δ = 0, mais son ordre doit être suivi. E22 : multiplier par la somme des distances.'
 c.eval_hints='DM : garder le signe de la différence optique. DS : les minima avec amplitudes inégales ne sont pas nuls ; en milieu uniforme, employer soit nδ avec λ0, soit δ avec λ0/n.'
 c.source('DS publié — Interférométrie stellaire',DS5,'DS5 du 21 janvier 2026, exercice 3, p. 3–4. Sélection : questions 1 à 9 ; 10 à 14 en prolongement guidé.',r'Refaire la géométrie de Young sous incidence inclinée ; suivre les conventions du schéma original. Réserver l’addition des deux figures au prolongement annoncé.',r'Le centre est $x_0=D\varepsilon$ et $i=\lambda D/a$. Deux étoiles incohérentes donnent la somme de deux intensités. Le contraste est $|\cos(2\pi a\varepsilon/\lambda)|$ ; la première annulation impose $2\varepsilon=\lambda/(2a_{\min})$. Avec les données originales, 600 nm et 71 mm, on obtient $4{,}225\times10^{-6}$ rad. Les deux figures se compensent sans annuler leur intensité totale.')
 c.source('DM publié — Réflexion sur un mur',DM6,'Le fichier lié comme DM5 porte le titre DM6, à rendre le 8 janvier 2026. Exercice 1, p. 1, questions 1 à 8.',r'Utiliser le dessin d’origine pour fixer les axes et le sens des deux ondes. Former la somme de surpressions avant de chercher les zones silencieuses.',r'Les surfaces silencieuses satisfont une différence de phase impaire de $\pi$. Les deux directions étant perpendiculaires, la norme du gradient de cette différence vaut $k\sqrt2$. Deux plans voisins sont donc distants de $d=2\pi/(k\sqrt2)=\lambda/\sqrt2$, mesuré perpendiculairement aux plans. À 440 Hz et 340 m/s, $d=0{,}546$ m. Une différence de coordonnées lue sur un axe ne donne pas directement cet espacement.')
 c.next='Le chapitre 10 approfondit la superposition de deux ondes de sens contraires et les modes d’une corde.'
 c.check('i-TP',600e-9*2/.0005,.0024)
 c.check('u-lambda-TP',600*sqrt((.2/24)**2+(.005/.5)**2+(.005/2)**2),7.952986860293434,0.01)
 c.check('contraste-D2',12/29,.41379310344827586)
 c.check('angle-D3',600e-9/(2*.075),4e-6)
 return c
